struct TaggedAttribute {
    std::uint32_t bodyPartID{};
    asn1kit::oid attrType{};
    std::vector<asn1kit::any> attrValues{};

    [[nodiscard]] TaggedAttributeCmcControlSetOpenView<TaggedAttribute> cmc_control_set() &;
    [[nodiscard]] TaggedAttributeCmcControlSetOpenView<const TaggedAttribute> cmc_control_set() const &;
    [[nodiscard]] TaggedAttributeCmcControlSetOpenView<asn1kit::open_owned_target<TaggedAttribute>> cmc_control_set() &&;
    TaggedAttributeCmcControlSetOpenView<const TaggedAttribute> cmc_control_set() const && = delete;
    [[nodiscard]] static TaggedAttributeCmcControlSetOpenView<asn1kit::open_factory_target<TaggedAttribute>> make_cmc_control_set();

    template <typename T>
    [[nodiscard]] static asn1kit::open_binding<asn1kit::default_open_context, asn1kit::oid, std::vector<T>> open_binding(asn1kit::oid key) {
        return {std::move(key)};
    }

    template <typename Context, typename T>
    [[nodiscard]] std::optional<std::vector<T>> try_decode(
        const asn1kit::open_binding<Context, asn1kit::oid, std::vector<T>>& binding) const {
        if (!(this->attrType == binding.key)) return std::nullopt;
        return asn1kit::decode_each<T>(attrValues);
    }

    template <typename Context, typename T>
    void set(const asn1kit::open_binding<Context, asn1kit::oid, std::vector<T>>& binding, const std::vector<T>& value) {
        this->attrType = binding.key;
        attrValues = asn1kit::encode_each(value);
    }

    template <typename Context, typename T>
    void set(const asn1kit::open_binding<Context, asn1kit::oid, std::vector<T>>& binding, const T& value) {
        set(binding, std::vector<T>{value});
    }

    template <typename Context, typename T>
    [[nodiscard]] static TaggedAttribute create(
        const asn1kit::open_binding<Context, asn1kit::oid, std::vector<T>>& binding, const std::vector<T>& value) {
        TaggedAttribute result{};
        result.set(binding, value);
        return result;
    }

    template <typename Context, typename T>
    [[nodiscard]] static TaggedAttribute create(
        const asn1kit::open_binding<Context, asn1kit::oid, std::vector<T>>& binding, const T& value) {
        return create(binding, std::vector<T>{value});
    }

    static constexpr bool match_tag(const asn1kit::tag& t) {
        return t.matches_ignore_constructed(asn1kit::tag::sequence);
    }

    static TaggedAttribute decode(asn1kit::reader& r, const asn1kit::tag& t = asn1kit::tag::sequence) {
        TaggedAttribute value{};
        r.with_sequence(t, [&](asn1kit::reader& inner) {
            value.bodyPartID = inner.read_uint32(asn1kit::tag::integer);
            value.attrType = inner.read_oid(asn1kit::tag::object_identifier);
            value.attrValues = inner.read_set_of<asn1kit::any>(asn1kit::tag::set, [&](asn1kit::reader& inner) {
                return inner.read_any();
            });
        });
        return value;
    }

    void encode(asn1kit::writer& w, const asn1kit::tag& t = asn1kit::tag::sequence) const {
        auto scope = w.enter_sequence(t);
        w.write_integer(asn1kit::tag::integer, this->bodyPartID);
        w.write_object_identifier(asn1kit::tag::object_identifier, this->attrType);
        w.write_set_of(asn1kit::tag::set, this->attrValues, [&](asn1kit::writer& inner, const auto& item) {
            inner.write_any(item);
        });
    }
};

